fn merge_cli_first<T: Clone>(cli_values: &[T], spec_values: &[T]) -> Vec<T> {
    cli_values
        .iter()
        .chain(spec_values.iter())
        .cloned()
        .collect()
}

fn merge_spec_first<T: Clone>(spec_values: &[T], cli_values: &[T]) -> Vec<T> {
    spec_values
        .iter()
        .chain(cli_values.iter())
        .cloned()
        .collect()
}

